// Fixed captured C2S vectors; expected plaintext from retained KR native emulation,
// CP057 native-stream.json/coalesced, not regenerated by this Rust encoder.
use kr_wire::{CodecError, Receiver, Width, decode, encode, read_uint, write_uint};
fn hex(s: &str) -> Vec<u8> {
    s.as_bytes()
        .as_chunks::<2>()
        .0
        .iter()
        .map(|b| u8::from_str_radix(std::str::from_utf8(b).unwrap(), 16).unwrap())
        .collect()
}
const FRAME0: &str = "0fc800000006000000ffffffff240000000200000002000000020000000000000001000000efb8903a1c1f9c12eec39f8a9ddd86b259db8f4c6e56e17ef219bbfc7f63aa54c02f19fb27";
const PLAIN0: &str = "5ba5a56996ca539496ca53950000000071b185885a5a5b96ca539596ca53955a96ca5395";
const FRAME1: &str =
    "0c0000000020020000ffffffff03000000020000000200000002000000000000000100000012746ee9";
const PLAIN1: &str = "a5695b";

#[test]
fn retained_native_encode_decode_and_all_stream_splits() {
    let first = hex(FRAME0);
    let second = hex(FRAME1);
    for (frame, plain, seq, opcode) in [
        (&first, hex(PLAIN0), 40, 6),
        (&second, hex(PLAIN1), 43, 544),
    ] {
        let packet = decode(frame, seq).unwrap();
        assert_eq!(packet.opcode, opcode);
        assert_eq!(packet.payload, plain);
        let header = frame[..37].try_into().unwrap();
        assert_eq!(encode(header, opcode, &plain, seq).unwrap(), *frame);
    }
    let stream = [first.as_slice(), second.as_slice()].concat();
    for split in 0..=stream.len() {
        let mut rx = Receiver::new(40);
        let mut received = Vec::new();
        for piece in [&stream[..split], &stream[split..]] {
            rx.push(piece).unwrap();
            while let Some(packet) = rx.next_packet().unwrap() {
                received.push(packet);
            }
        }
        assert_eq!(received.len(), 2);
        assert_eq!(received[0].payload, hex(PLAIN0));
        assert_eq!(received[1].payload, hex(PLAIN1));
        assert_eq!(rx.sequence(), 46);
        rx.finish().unwrap();
    }
}
#[test]
fn invalid_crc_never_advances_or_affects_another_connection() {
    let mut bad = hex(FRAME0);
    *bad.last_mut().unwrap() ^= 1;
    let mut rx = Receiver::new(40);
    rx.push(&bad).unwrap();
    assert_eq!(rx.next_packet(), Err(CodecError::Checksum));
    assert_eq!(rx.sequence(), 40);
    let mut other = Receiver::new(40);
    other.push(&hex(FRAME0)).unwrap();
    assert_eq!(other.next_packet().unwrap().unwrap().sequence, 40);
    assert_eq!(other.sequence(), 43);
    let fresh = Receiver::new(40);
    assert_eq!(fresh.sequence(), 40);
}
#[test]
fn incomplete_eof_and_oversize_are_bounded_errors() {
    let f = hex(FRAME0);
    for size in 1..f.len() {
        let mut rx = Receiver::new(40);
        rx.push(&f[..size]).unwrap();
        assert!(rx.next_packet().unwrap().is_none());
        assert_eq!(rx.finish(), Err(CodecError::TruncatedEof));
        assert_eq!(rx.sequence(), 40);
    }
    let mut header = [0; 38];
    header[13..17].copy_from_slice(&u32::MAX.to_le_bytes());
    let mut rx = Receiver::new(40);
    rx.push(&header).unwrap();
    assert_eq!(rx.next_packet(), Err(CodecError::FrameTooLarge));
    assert_eq!(rx.sequence(), 40);
    assert_eq!(rx.push(&vec![0; 65536]), Err(CodecError::BufferFull));
    assert_eq!(
        encode(&[0; 37], 1, &vec![0; 65536], 40),
        Err(CodecError::FrameTooLarge)
    );
}
#[test]
fn native_typed_helper_examples_and_unsigned_bounds() {
    assert_eq!(write_uint(0, Width::U16).unwrap(), hex("a569"));
    assert_eq!(write_uint(65535, Width::U16).unwrap(), hex("5a96"));
    assert_eq!(write_uint(0, Width::U8).unwrap(), hex("5a"));
    assert_eq!(write_uint(255, Width::U8).unwrap(), hex("a5"));
    assert_eq!(read_uint(&hex("5a96"), Width::U16).unwrap(), 65535);
    assert_eq!(write_uint(256, Width::U8), Err(CodecError::FieldOutOfRange));
    assert_eq!(read_uint(&[], Width::U32), Err(CodecError::InvalidLength));
}

#[test]
fn sequence_wrap_and_exact_maximum_frame_are_design_regressions() {
    // These inputs exercise implementation bounds, not additional native proof.
    let body = vec![0; kr_wire::MAX_FRAME_LEN - kr_wire::FRAME_OVERHEAD];
    let frame = encode(&[0; 37], 1, &body, u32::MAX - 1).unwrap();
    assert_eq!(frame.len(), kr_wire::MAX_FRAME_LEN);
    let mut rx = Receiver::new(u32::MAX - 1);
    rx.push(&frame).unwrap();
    assert_eq!(rx.next_packet().unwrap().unwrap().payload, body);
    assert_eq!(rx.sequence(), 1);
    rx.finish().unwrap();
}
